//! Producer-owned formal parser records on the existing actual Header owner.
//! Coordinates/registrations are DATA; only the current source view maps them.
use dm_syntax::{Span,SettingAdmission,SettingRootLease};
use std::{io,mem::size_of};
#[derive(Clone,Copy,Debug,Eq,PartialEq)]pub enum OriginalFormalNoticeLevel{Error,Warning,Hint}
#[derive(Clone,Copy,Debug,Eq,PartialEq)]pub(super) enum Kind{Var,Static,InBeforeAs,Semicolon,BadInput,LocateInArgument,LocateTupleIn,MissingMember,EmptyParentheses}
#[derive(Clone,Copy,Debug,Eq,PartialEq)]pub struct OriginalFormalNotice{at:Span,kind:Kind}
impl OriginalFormalNotice{
 pub(super) fn new(at:Span,kind:Kind)->Self{Self{at,kind}}
 pub(super) fn from_primitive(notice:dm_syntax::OriginalInputNotice)->Self{use dm_syntax::OriginalInputNoticeKind as N;Self{at:notice.span(),kind:match notice.kind(){N::BadInputType=>Kind::BadInput,N::InPrecedesAs=>Kind::InBeforeAs,N::LocateInArgument=>Kind::LocateInArgument,N::LocateTupleIn=>Kind::LocateTupleIn,N::EmptyParentheses=>Kind::EmptyParentheses}}}
 pub fn span(self)->Span{self.at}
 pub fn registration(self)->(Option<&'static str>,OriginalFormalNoticeLevel){use OriginalFormalNoticeLevel as L;match self.kind{Kind::Var=>(Some("var_in_proc_parameter"),L::Hint),Kind::Static=>(Some("static_in_proc_parameter"),L::Warning),Kind::InBeforeAs=>(Some("in_precedes_as"),L::Warning),Kind::Semicolon=>(Some("semicolon_in_proc_parameter"),L::Warning),Kind::BadInput|Kind::MissingMember=>(None,L::Error),Kind::LocateInArgument|Kind::LocateTupleIn|Kind::EmptyParentheses=>(None,L::Warning)}}
 pub fn family(self)->&'static str{match self.kind{Kind::Var=>"var_in_proc_parameter",Kind::Static=>"static_in_proc_parameter",Kind::InBeforeAs=>"in_precedes_as",Kind::Semicolon=>"semicolon_in_proc_parameter",Kind::BadInput=>"bad_input_type",Kind::MissingMember=>"missing_member_identifier",Kind::LocateInArgument=>"locate_in_argument",Kind::LocateTupleIn=>"locate_tuple_in",Kind::EmptyParentheses=>"empty_parentheses"}}
 pub fn static_message(self)->Option<&'static str>{Some(match self.kind{Kind::Var=>"'var/' is unnecessary here",Kind::EmptyParentheses=>"'()' should be replaced with 'null'",Kind::Static=>"'static/' has no effect here",Kind::InBeforeAs=>"'as' clause should precede 'in' clause, and is being ignored",Kind::Semicolon=>"Extraneous ';' in proc parameter",Kind::LocateInArgument=>"bad `locate(X in Y)`, should be `locate(X) in Y`",Kind::LocateTupleIn=>"bad 'locate(x, y, z) in'",Kind::BadInput|Kind::MissingMember=>return None})}
 pub(crate) fn needs_rendered_message(self)->bool{matches!(self.kind,Kind::MissingMember)}
 pub fn message_width(self,value:Option<&str>)->Result<usize,&'static str>{if let Some(text)=self.static_message(){return Ok(text.len())}let text=value.ok_or("actual dynamic formal notice payload absent")?;if self.needs_rendered_message(){Ok(text.len())}else{text.len().checked_add("bad input type: ''".len()).ok_or("formal parser notice width overflow")}}
 pub fn write_message(self,value:Option<&str>,out:&mut dyn std::fmt::Write)->std::fmt::Result{if let Some(text)=self.static_message(){return out.write_str(text)}let value=value.ok_or(std::fmt::Error)?;if self.needs_rendered_message(){out.write_str(value)}else{write!(out,"bad input type: '{}'",value)}}
 pub(super) fn is_semicolon(self)->bool{self.kind==Kind::Semicolon}
 pub fn value_span(self)->Option<Span>{matches!(self.kind,Kind::BadInput).then_some(self.at)}
 pub(crate) fn checked_shift(self,offset:usize)->io::Result<Self>{Ok(Self{at:Span::new(self.at.start.checked_add(offset).ok_or(io::ErrorKind::InvalidInput)?,self.at.end.checked_add(offset).ok_or(io::ErrorKind::InvalidInput)?),kind:self.kind})}
}
pub(super) struct Entry{pub header:usize,pub notice:OriginalFormalNotice,message:Option<String>}
pub(super) struct FormalNotices{rows:Vec<Entry>,credit:SettingRootLease}
impl std::fmt::Debug for FormalNotices{fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result{f.debug_struct("FormalNotices").field("count",&self.rows.len()).finish()}}
fn checkpoint(a:&SettingAdmission<'_>)->io::Result<()>{a.checkpoint().map_err(|e|a.take_operational_error().unwrap_or(e))}
impl FormalNotices{
 #[cfg(debug_assertions)]
 pub(super) fn retained_bytes_for_trace(&self)->usize{self.credit.bytes()}
 pub fn new(a:&SettingAdmission<'_>)->io::Result<Self>{let credit=a.reserve(0).map_err(|e|a.take_operational_error().unwrap_or(e))?;Ok(Self{rows:Vec::new(),credit})}
 pub fn is_admitted_by(&self,a:&SettingAdmission<'_>)->bool{a.matches_lease_domain(&self.credit)}
 pub fn push(&mut self,header:usize,notice:OriginalFormalNotice,a:&SettingAdmission<'_>)->io::Result<()>{self.push_entry(header,notice,None,a)}
 pub fn push_rendered(&mut self,header:usize,notice:OriginalFormalNotice,a:&SettingAdmission<'_>,render:impl FnOnce(&mut dyn std::fmt::Write)->std::fmt::Result)->io::Result<()>{checkpoint(a)?;if !self.is_admitted_by(a)||!notice.needs_rendered_message(){return Err(io::ErrorKind::InvalidInput.into())}let message=dm_syntax::admitted_message_using(a,&mut self.credit,render)?;self.push_entry(header,notice,Some(message),a)}
 pub fn rendered_message(&self,notice:OriginalFormalNotice)->Result<&str,&'static str>{self.rows.iter().find(|row|row.notice==notice).and_then(|row|row.message.as_deref()).ok_or("actual rendered formal notice owner/payload absent")}
 fn push_entry(&mut self,header:usize,notice:OriginalFormalNotice,message:Option<String>,a:&SettingAdmission<'_>)->io::Result<()>{checkpoint(a)?;if !self.is_admitted_by(a)||self.rows.last().is_some_and(|row|row.header>header){return Err(io::ErrorKind::InvalidInput.into())}
  if self.rows.len()==self.rows.capacity(){let capacity=self.rows.capacity().max(2).checked_mul(2).ok_or(io::ErrorKind::OutOfMemory)?;let peak=capacity.checked_mul(4).and_then(|n|n.checked_mul(size_of::<Entry>())).ok_or(io::ErrorKind::OutOfMemory)?;let previous=self.rows.capacity().checked_mul(size_of::<Entry>()).ok_or(io::ErrorKind::OutOfMemory)?;a.grow(&mut self.credit,peak).map_err(|e|a.take_operational_error().unwrap_or(e))?;self.rows.try_reserve_exact(capacity-self.rows.len()).map_err(|error|io::Error::new(io::ErrorKind::OutOfMemory,error))?;let current=self.rows.capacity().checked_mul(size_of::<Entry>()).ok_or(io::ErrorKind::OutOfMemory)?;if current>peak{return Err(io::ErrorKind::OutOfMemory.into())}let free=previous.checked_add(peak).and_then(|n|n.checked_sub(current)).ok_or(io::ErrorKind::InvalidData)?;a.shrink(&mut self.credit,free).map_err(|e|a.take_operational_error().unwrap_or(e))?;
  }self.rows.push(Entry{header,notice,message});checkpoint(a)
 }
 pub fn for_header(&self,header:usize)->&[Entry]{let start=self.rows.partition_point(|row|row.header<header);let end=self.rows.partition_point(|row|row.header<=header);&self.rows[start..end]}
 pub fn all(&self)->&[Entry]{&self.rows}
 pub fn visit_storage(&self,mut visit:impl FnMut(usize,usize,usize)){if self.rows.capacity()!=0{visit(self.rows.as_ptr()as usize,self.rows.len()*size_of::<Entry>(),self.rows.capacity()*size_of::<Entry>())}for row in &self.rows{if let Some(message)=&row.message{visit(message.as_ptr()as usize,message.len(),message.capacity())}}self.credit.visit_counter_storage(|address,bytes|visit(address,bytes,bytes));}
}
/// Pinned actual InputType::from_str table (0290 ast.rs507..531), used only on
/// an identifier just consumed by the SAME native annotation producer.
pub(super) fn original_input_name(text:&str)->bool{matches!(text,"mob"|"obj"|"text"|"num"|"file"|"turf"|"key"|"null"|"area"|"icon"|"sound"|"message"|"anything"|"password"|"command_text"|"color"|"movable"|"atom"|"list")}

#[cfg(test)]mod tests{
 use super::*;use std::sync::{atomic::{Ordering}};
 #[test]fn actual_formal_notice_directory_is_funded_before_growth_and_drops_only_after_rows(){
  let used=dm_syntax::SettingChargeCounter::try_new(dm_syntax::SettingChargeCounter::root_allocation_bytes()).unwrap();let a=SettingAdmission::new(&used,1<<20,&||Ok(()));let mut ledger=FormalNotices::new(&a).unwrap();let notice=OriginalFormalNotice::new(Span::new(3,4),Kind::Var);ledger.push(1,notice,&a).unwrap();ledger.push(1,OriginalFormalNotice::new(Span::new(3,4),Kind::Static),&a).unwrap();ledger.push(9,notice,&a).unwrap();assert_eq!(ledger.for_header(1).len(),2);assert_eq!(ledger.for_header(9).len(),1);let funded=used.load(Ordering::Relaxed);assert!(funded>=ledger.rows.capacity()*size_of::<Entry>());assert!(ledger.push(0,notice,&a).is_err());let foreign=dm_syntax::SettingChargeCounter::try_new(dm_syntax::SettingChargeCounter::root_allocation_bytes()).unwrap();let other=SettingAdmission::new(&foreign,1<<20,&||Ok(()));assert!(ledger.push(10,notice,&other).is_err());drop(ledger);assert_eq!(used.load(Ordering::Relaxed),dm_syntax::SettingChargeCounter::root_allocation_bytes());
  let tiny=SettingAdmission::new(&used,dm_syntax::SettingChargeCounter::root_allocation_bytes() + (1),&||Ok(()));let mut ledger=FormalNotices::new(&tiny).unwrap();assert_eq!(ledger.push(1,notice,&tiny).unwrap_err().kind(),io::ErrorKind::OutOfMemory);assert_eq!(ledger.rows.capacity(),0);drop(ledger);assert_eq!(used.load(Ordering::Relaxed),dm_syntax::SettingChargeCounter::root_allocation_bytes());
 }
 #[test]fn actual_formal_notice_checkpoint_preserves_typed_io_before_output_growth(){let used=dm_syntax::SettingChargeCounter::try_new(dm_syntax::SettingChargeCounter::root_allocation_bytes()).unwrap();let ok=SettingAdmission::new(&used,1<<20,&||Ok(()));let mut ledger=FormalNotices::new(&ok).unwrap();let bad=||Err(io::Error::from_raw_os_error(1450));let a=SettingAdmission::new(&used,1<<20,&bad);let error=ledger.push(1,OriginalFormalNotice::new(Span::new(0,1),Kind::Var),&a).unwrap_err();assert_eq!(error.raw_os_error(),Some(1450));assert_eq!(ledger.rows.capacity(),0);drop(ledger);assert_eq!(used.load(Ordering::Relaxed),dm_syntax::SettingChargeCounter::root_allocation_bytes());}
 #[test]fn rendered_member_notice_owns_actual_message_credit_and_rejects_foreign_or_failed_output(){
  let used=dm_syntax::SettingChargeCounter::try_new(dm_syntax::SettingChargeCounter::root_allocation_bytes()).unwrap();let a=SettingAdmission::new(&used,1<<20,&||Ok(()));let mut notices=FormalNotices::new(&a).unwrap();let actual=OriginalFormalNotice::new(Span::new(10,11),Kind::MissingMember);notices.push_rendered(0,actual,&a,|out|dm_syntax::write_original_input_failure(out,Some(dm_syntax::OriginalTokenValue::Punct(")")),dm_syntax::OriginalInputExpected::Identifier)).unwrap();assert_eq!(notices.rendered_message(actual).unwrap(),"got ')', expected one of: identifier");let mut rendered=String::new();actual.write_message(Some(notices.rendered_message(actual).unwrap()),&mut rendered).unwrap();assert_eq!(rendered.len(),actual.message_width(Some(&rendered)).unwrap());assert!(used.load(Ordering::Acquire)>dm_syntax::SettingChargeCounter::root_allocation_bytes());let foreign_used=dm_syntax::SettingChargeCounter::try_new(dm_syntax::SettingChargeCounter::root_allocation_bytes()).unwrap();let foreign=SettingAdmission::new(&foreign_used,1<<20,&||Ok(()));assert_eq!(notices.push_rendered(0,actual,&foreign,|_|panic!("foreign credit must fail before rendering")).unwrap_err().kind(),io::ErrorKind::InvalidInput);let fail=||Err(io::Error::from_raw_os_error(1450));let failed=SettingAdmission::new(&used,1<<20,&fail);assert_eq!(notices.push_rendered(0,actual,&failed,|_|panic!("real1450 must precede any writer growth")).unwrap_err().raw_os_error(),Some(1450));drop(notices);assert_eq!(used.load(Ordering::Acquire),dm_syntax::SettingChargeCounter::root_allocation_bytes());assert_eq!(foreign_used.load(Ordering::Acquire),dm_syntax::SettingChargeCounter::root_allocation_bytes());
 }

}
